#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <pthread.h>

#define MAX_LABELS 64
#define MAX_KEY_LEN 128
#define MAX_VAL_LEN 256
#define CONFIG_PORT 9090
#define PROTO_MAGIC 0x4B4C4F47

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_VAL_LEN];
} label_t;

typedef struct {
    label_t labels[MAX_LABELS];
    int count;
    char log_path[256];
    char node_name[128];
    int verbosity;
    int flush_interval;
    char output_format[64];
} agent_config_t;

static agent_config_t g_config;
static pthread_mutex_t g_config_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct __attribute__((packed)) {
    uint32_t magic;
    uint16_t op_code;
    uint16_t num_entries;
    uint32_t payload_len;
} config_header_t;

static int find_label_index(const char *key) {
    for (int i = 0; i < g_config.count; i++) {
        if (strncmp(g_config.labels[i].key, key, MAX_KEY_LEN) == 0)
            return i;
    }
    return -1;
}

static int apply_label_update(const char *key, const char *value) {
    pthread_mutex_lock(&g_config_mutex);
    int idx = find_label_index(key);
    if (idx >= 0) {
        strncpy(g_config.labels[idx].value, value, MAX_VAL_LEN - 1);
        g_config.labels[idx].value[MAX_VAL_LEN - 1] = '\0';
    } else {
        if (g_config.count < MAX_LABELS) {
            strncpy(g_config.labels[g_config.count].key, key, MAX_KEY_LEN - 1);
            g_config.labels[g_config.count].key[MAX_KEY_LEN - 1] = '\0';
            strncpy(g_config.labels[g_config.count].value, value, MAX_VAL_LEN - 1);
            g_config.labels[g_config.count].value[MAX_VAL_LEN - 1] = '\0';
            g_config.count++;
        }
    }
    pthread_mutex_unlock(&g_config_mutex);
    return 0;
}

static int apply_field_update(const char *field_path, const char *value) {
    /* Handle dotted field paths like "config.log_path" or "config.verbosity" */
    const char *field = field_path;
    if (strncmp(field_path, "config.", 7) == 0)
        field = field_path + 7;

    pthread_mutex_lock(&g_config_mutex);
    if (strcmp(field, "node_name") == 0) {
        strncpy(g_config.node_name, value, sizeof(g_config.node_name) - 1);
        g_config.node_name[sizeof(g_config.node_name) - 1] = '\0';
    } else if (strcmp(field, "verbosity") == 0) {
        int v = atoi(value);
        if (v >= 0 && v <= 5)
            g_config.verbosity = v;
    } else if (strcmp(field, "output_format") == 0) {
        if (strcmp(value, "json") == 0 || strcmp(value, "text") == 0 || strcmp(value, "csv") == 0) {
            strncpy(g_config.output_format, value, sizeof(g_config.output_format) - 1);
            g_config.output_format[sizeof(g_config.output_format) - 1] = '\0';
        }
    } else {
        pthread_mutex_unlock(&g_config_mutex);
        return -1;
    }
    pthread_mutex_unlock(&g_config_mutex);
    return 0;
}

static int parse_and_apply_entries(const char *payload, uint16_t num_entries, uint32_t payload_len, uint16_t op_code) {
    const char *ptr = payload;
    const char *end = payload + payload_len;
    for (uint16_t i = 0; i < num_entries; i++) {
        if (ptr >= end) return -1;
        uint8_t key_len = (uint8_t)*ptr++;
        if (key_len == 0 || key_len >= MAX_KEY_LEN) return -1;
        if (ptr + key_len > end) return -1;
        char key[MAX_KEY_LEN] = {0};
        memcpy(key, ptr, key_len);
        ptr += key_len;

        if (ptr >= end) return -1;
        uint8_t val_len = (uint8_t)*ptr++;
        if (ptr + val_len > end) return -1;
        char value[MAX_VAL_LEN] = {0};
        if (val_len > 0) {
            memcpy(value, ptr, val_len);
            ptr += val_len;
        }

        /* Only label updates allowed via network */
        if (op_code == 0x01) {
            apply_label_update(key, value);
        } else {
            return -1;
        }
    }
    return 0;
}

static int validate_header(config_header_t *hdr) {
    if (hdr->magic != PROTO_MAGIC) return -1;
    if (hdr->op_code != 0x01) return -1;
    if (hdr->num_entries > MAX_LABELS) return -1;
    if (hdr->payload_len > 8192) return -1;
    return 0;
}

static void *config_listener(void *arg) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in addr = {.sin_family = AF_INET, .sin_port = htons(CONFIG_PORT), .sin_addr.s_addr = htonl(INADDR_LOOPBACK)};
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    bind(server_fd, (struct sockaddr*)&addr, sizeof(addr));
    listen(server_fd, 5);

    while (1) {
        int client_fd = accept(server_fd, NULL, NULL);
        if (client_fd < 0) continue;

        config_header_t hdr;
        if (recv(client_fd, &hdr, sizeof(hdr), MSG_WAITALL) != sizeof(hdr)) {
            close(client_fd); continue;
        }
        if (validate_header(&hdr) != 0) {
            close(client_fd); continue;
        }

        char *payload = malloc(hdr.payload_len + 1);
        if (!payload) { close(client_fd); continue; }
        payload[hdr.payload_len] = '\0';

        ssize_t received = recv(client_fd, payload, hdr.payload_len, MSG_WAITALL);
        if (received == (ssize_t)hdr.payload_len) {
            parse_and_apply_entries(payload, hdr.num_entries, hdr.payload_len, hdr.op_code);
        }
        free(payload);
        close(client_fd);
    }
    return NULL;
}

static void init_defaults(void) {
    memset(&g_config, 0, sizeof(g_config));
    strncpy(g_config.log_path, "/var/log/klog-agent/output.log", sizeof(g_config.log_path) - 1);
    strncpy(g_config.node_name, "default-node", sizeof(g_config.node_name) - 1);
    g_config.verbosity = 1;
    g_config.flush_interval = 5;
    strncpy(g_config.output_format, "json", sizeof(g_config.output_format) - 1);
}

int main(int argc, char *argv[]) {
    init_defaults();
    pthread_t listener_thread;
    pthread_create(&listener_thread, NULL, config_listener, NULL);
    /* Main logging loop would go here */
    while (1) {
        pthread_mutex_lock(&g_config_mutex);
        FILE *f = fopen(g_config.log_path, "a");
        if (f) {
            fprintf(f, "{\"node\":\"%s\",\"verbosity\":%d}\n", g_config.node_name, g_config.verbosity);
            fclose(f);
        }
        pthread_mutex_unlock(&g_config_mutex);
        sleep(g_config.flush_interval > 0 ? g_config.flush_interval : 5);
    }
    return 0;
}
